+// PeekWithExpiry returns the key value, its recorded expiration time, and a boolean
+// indicating if the key was found and has not yet expired. This call does not update
+// the "recently used"-ness of the key.
+func (c *LRU[K, V]) PeekWithExpiry(key K) (value V, expiresAt time.Time, ok bool) {
+	c.mu.Lock()
+	defer c.mu.Unlock()
+	var ent *internal.Entry[K, V]
+	if ent, ok = c.items[key]; ok {
+		// Expired item check
+		if !c.cleanupStopped && time.Now().After(ent.ExpiresAt) {
+			return value, time.Time{}, false
+		}
+		return ent.Value, ent.ExpiresAt, true
+	}
+	return
+}
