+    /// Increments the minor version number (minor + 1, patch 0).
+    /// Resets pre-release and build metadata to empty.
+    pub fn bump_minor(&self) -> Self {
+        Version {
+            major: self.major,
+            minor: self.minor.saturating_add(1),
+            patch: 0,
+            pre: Prerelease::EMPTY,
+            build: BuildMetadata::EMPTY,
+        }
+    }
+
+    /// Increments the patch version number (patch + 1).
+    /// Resets pre-release and build metadata to empty.
+    pub fn bump_patch(&self) -> Self {
+        Version {
+            major: self.major,
+            minor: self.minor,
+            patch: self.patch.saturating_add(1),
+            pre: Prerelease::EMPTY,
+            build: BuildMetadata::EMPTY,
+        }
+    }
 }

