-		}
+		},
+
+		/**
+		 * Invoke all handlers for the given type asynchronously.
+		 * Type-matched handlers are called first, then '*' wildcard handlers.
+		 * Each handler is awaited before the next one is called.
+		 * Handlers may return a Promise or a plain value.
+		 * If any handler throws or Rejects, subsequent handlers are not called
+		 * and emitAsync rejects with that error.
+		 *
+		 * @param {string|symbol} type The event type to invoke
+		 * @param {Any} evt Any value (object is recommended and powerful), passed to each handler
+		 * @returns Promise resolving to the number of handlers called on success
+		 * @memberOf mitt
+		 */
+		async emitAsync<Key extends keyof Events>(type: Key, evt: Events[Key]) {
+			let count = 0;
+
+			// First call type-specific handlers
+			let handlers = all!.get(type);
+			if (handlers) {
+				for (const handler of handlers.slice()) {
+					await Promise.resolve((handler as Handler<Events[Key]>)(evt!));
+					count++;
+				}
+			}
+
+			// Then call wildcard handlers with (type, evt)
+			handlers = all!.get('*');
+			if (handlers) {
+				for (const handler of handlers.slice()) {
+					await Promise.resolve(
+						(handler as WildcardHandler<Events>)(type, evt!)
+					);
+					count++;
+				}
+			}
+
+			return count;
+		},
 	};
 }
